# =============================================================================
# user_step3.R - 用户第三步驱动程序：阶段 A 无标记 isoPSV 评估。
# user_step3.R - user step 3 driver: stage A unlabeled isoPSV evaluation.
# 读取第三步参数文件（由第二步自动生成）：merge_result、
# Reads the step-3 parameter file (auto-generated by step 2): merge_result,
# 阶段 A 权重/阈值以及 pDeep2 predict.txt 路径。
# stage A weights/threshold and the pDeep2 predict.txt path. There is NO
# 单次计算无组概念；无标记 MGF 目录为 <config dir>/unlabeled（单组流程，无组名）
# no group concept for a single computation; the unlabeled MGF folder is
# <config dir>/unlabeled (single-sample workflow, no group names).
#
# 用法：
# Usage:
#   运行方式：Rscript user_step3.R
#   Rscript user_step3.R
# 第三步参数文件路径放在环境变量 CONFIG3 中。
# with the step-3 parameter file path in the environment variable CONFIG3.
# =============================================================================

# 加载通用工具与核心计算模块（ACS 核心、成对参数、MGF 读取等）
# Load the shared utilities and the core computation modules (ACS core, paired params, MGF reader, etc.)
# 核心库统一入口（N-1，2026-09-25）：按 --file= 定位代码目录、绝对路径加载
# （boot.R），替代裸相对 source——此前仅当启动 cwd 恰为 code/ 时成立。
# core-library entry (N-1, 2026-09-25): locate the code dir via --file= and
# load by absolute path (boot.R), replacing the bare relative source().
sd0 <- dirname(tryCatch(normalizePath(sub("^--file=", "",
    grep("^--file=", commandArgs(FALSE), value = TRUE)[1]), winslash = "/"),
    error = function(e) ""))
if (is.na(sd0) || !dir.exists(sd0)) sd0 <- getwd()
source(file.path(sd0, "boot.R"))

# 读取第三步参数文件（路径来自环境变量 CONFIG3），并取得配置所在目录
# Read the step-3 parameter file (path from env var CONFIG3) and get the config directory
cfg3_path <- Sys.getenv("CONFIG3")
if (!nzchar(cfg3_path)) stop("set CONFIG3 to the step-3 parameter file path")
cfg3 <- read_param_file(cfg3_path)
cfg_dir <- cfg3$config_dir
if (is.null(cfg_dir) || length(cfg_dir) == 0 || !nzchar(cfg_dir[1]))   # 2026-09-26 审查 P0-3/P3-6：config_dir 缺失/为空时给可读报错
  stop("config_step3 的 config_dir 缺失或为空，请检查配置（或删除 result_* 后重跑）
config_dir missing/empty in config_step3")
# 结果文件夹（RESULT_DIR 由总程序注入；独立运行按时间戳定位/新建）
# result folder (RESULT_DIR injected by the master; standalone runs locate/create by timestamp)
result_dir <- get_result_dir(cfg_dir)

# 解析多引擎合并结果路径，并读取基础配置（策略 1）
# Resolve the multi-engine merge result path and read the base config (strategy 1)
merged_file <- resolve_cfg_paths(cfg3, "merge_result")[1]
# 注：config_step3 的 base_config 直接指向 config_step1（make_step3_config
# 口径）——因此这里的 base_cfg 就是 config_step1（含 proteogenomics_mode、
# fasta 等第一步键），门控取值循环 base_cfg+cfg3 已覆盖第一步。
base_cfg <- read_param_file(resolve_cfg_paths(cfg3, "base_config")[1])
# 工作流程门控（proteogenomics_mode，2026-09-27 用户口径）：0=全量模式
# （默认，所有谱竞争验证）；1=纯蛋白质基因组学模式——只对含非参考库候选的
# 谱做竞争验证，已注释谱标记 annotated_skipped 并跳过错误校正；2=已注释
# 肽段矫正模式——只矫正已注释谱，新肽候选谱标记 novel_skipped 并跳过。
# 定侧口径与两分法报告一致：以原始鉴定（a 槽蛋白）定侧——Proteins 列任一
# 蛋白命中用户 FASTA 即"已注释"；Proteins 空值按新肽候选侧处理。被跳过的
# 谱清单写入 pg_skipped.tsv 供总程序补记分类表（补记结论按模式取
# annotated_skipped / novel_skipped）。
pg_mode <- "0"
for (src in list(base_cfg, cfg3)) {
  if (!is.null(src$proteogenomics_mode) && length(src$proteogenomics_mode) > 0 &&
      tail(src$proteogenomics_mode, 1) %in% c("0", "1", "2")) {
    pg_mode <- tail(src$proteogenomics_mode, 1)
  }
}
if (pg_mode %in% c("1", "2")) {
  cat(if (pg_mode == "1")
    "==== 纯蛋白质基因组学模式：仅新肽段/新基因候选谱参与竞争验证 ====\n"
    else "==== 已注释肽段矫正模式：仅已注释谱参与错误校正 ====\n")
  cat(if (pg_mode == "1")
    "==== pure proteogenomics mode: only novel-candidate spectra are validated ====\n"
    else "==== annotated-correction mode: only annotated spectra are corrected ====\n")
  mrg <- read.delim(merged_file, sep = "\t", stringsAsFactors = FALSE,
                    check.names = FALSE, na.strings = character(0))
  fa_acc <- character(0)
  if (!is.null(base_cfg$fasta) && length(base_cfg$fasta) > 0) {
    fa_file <- resolve_cfg_paths(base_cfg, "fasta")[1]
    if (nzchar(fa_file) && file.exists(fa_file)) {
      fa_acc <- unique(names(read_fasta(fa_file)))
    }
  }
  prot_col <- if ("Proteins" %in% colnames(mrg)) mrg$Proteins else {
    if ("a.Proteins" %in% colnames(mrg)) mrg$a.Proteins else rep("", nrow(mrg))
  }
  # v1.0（工作站反馈缺陷2/4）：分侧改 fa_annotated_proteins 三口径
  # （accession / 序列级 I-L 归一 / CON_ 污染库）
  seq_col <- if ("a.Sequence" %in% colnames(mrg)) as.character(mrg$a.Sequence)
             else if ("Sequence" %in% colnames(mrg)) as.character(mrg$Sequence)
             else rep("", nrow(mrg))
  in_fasta <- fa_annotated_proteins(as.character(prot_col), seq_col,
                                    if (nzchar(fa_file)) fa_file else character(0))
  keep <- if (pg_mode == "1") !in_fasta else in_fasta
  cat(sprintf("[流程门控] 总谱 %d：目标侧 %d（竞争验证/矫正）/ 跳过 %d\n",
              nrow(mrg), sum(keep), sum(!keep)))
  skip_f <- file.path(result_dir, "1.unlabeled_result", "pg_skipped.tsv")
  dir.create(file.path(result_dir, "1.unlabeled_result"), showWarnings = FALSE)
  writeLines(unique(as.character(mrg$File_Name[!keep])), skip_f, useBytes = TRUE)
  pg_file <- file.path(result_dir, "merge", "merged_pg_target.spectra")
  write.table(mrg[keep, , drop = FALSE], pg_file, sep = "\t",
              row.names = FALSE, col.names = TRUE, quote = FALSE)
  merged_file <- pg_file
  cat("[流程门控] 目标侧合并件：", pg_file, "（", sum(keep), " 行）\n", sep = "")
}
# 枚举无标记 MGF 目录下逐 raw 的 mgf（排除合并文件 unlabeled.mgf）
# List the per-raw mgfs under the unlabeled MGF folder (merged unlabeled.mgf excluded)
unlabeled_dir <- file.path(cfg_dir, "unlabeled")
unlabeled_files <- sort(list.files(unlabeled_dir, pattern = "\\.mgf$", full.names = TRUE))
unlabeled_files <- unlabeled_files[basename(unlabeled_files) != "unlabeled.mgf"]
# 解析 pDeep2 预测结果路径，以及阶段 A 的权重向量与阈值；
# use_pdeep2=0 时 predict_file 置空——预测指标按缺省处理（不填 0、标注、投票降级）
# Resolve the pDeep2 prediction path and the stage A weight vector / threshold;
# when use_pdeep2=0 the predict_file is empty - the predict metric is treated
# as missing (never 0, flagged, dropped from the votes)
use_pd2 <- if (!is.null(cfg3$use_pdeep2) && length(cfg3$use_pdeep2) > 0) tail(cfg3$use_pdeep2, 1) else "1"
predict_file <- if (identical(use_pd2, "0")) "" else {
  pf <- resolve_cfg_paths(cfg3, "predict_file")
  if (length(pf) == 0 || is.na(pf[1])) "" else pf[1]
}
wA_raw <- if (!is.null(cfg3$weights_A) && length(cfg3$weights_A) > 0) tail(cfg3$weights_A, 1) else ""
wA <- as.numeric(strsplit(wA_raw, ",")[[1]])
if (length(wA) == 0 || any(is.na(wA))) {
  stop("config_step3.txt 缺少 weights_A（应为逗号分隔的权重）\nweights_A missing or invalid (expect comma-separated weights)")
}
if (length(wA) != 4L) {
  stop(sprintf("weights_A 应为 4 个值（ul_by,ul_all,ul_cov,predict），当前 %d 个：%s\nweights_A must have exactly 4 values (ul_by,ul_all,ul_cov,predict), got %d: %s",
      length(wA), wA_raw, length(wA), wA_raw))
}
thrA_raw <- if (!is.null(cfg3$threshold_A) && length(cfg3$threshold_A) > 0) tail(cfg3$threshold_A, 1) else NA
thrA <- as.numeric(thrA_raw)
if (is.na(thrA)) stop("config_step3.txt 缺少 threshold_A\nthreshold_A missing")
out_dir <- file.path(result_dir, "1.unlabeled_result")

# 打印本步骤运行信息：MGF 数量、预测文件路径、权重与阈值
# Print the run info for this step: MGF count, prediction path, weights and threshold
cat("==== [用户第三步] 阶段 A 无标记 isoPSV 评估 ====\n")
cat("==== [User Step 3] stage A evaluation ====\n")
cat("unlabeled MGFs:", length(unlabeled_files),
    "| predict_file:", predict_file, "\n")
cat("weights_A:", paste(wA, collapse = ","), "| threshold_A:", thrA, "\n")

# 评估可用计算资源（核数）；环境变量 WORKER_CORES 可作为工作进程数的可选覆盖
# Assess the available compute resources (cores); WORKER_CORES provides an optional worker-count override
max_cores <- assess_resources(c(unlabeled_files, if (nzchar(predict_file)) predict_file))
wc <- Sys.getenv("WORKER_CORES")
wci <- suppressWarnings(as.integer(wc))
worker_cores <- if (nzchar(wc) && !is.na(wci) && wci >= 1L) wci else NULL
# 调用阶段 A 评估：对无标记谱按多引擎候选计算 ACS、打分判定并写出 stageA 报告
# Call the stage A evaluation: score and judge the five-strategy candidates on the unlabeled spectra via ACS, then write the stageA report
# v1.0（无标记通道=0）：NeuCode 等全标记样本——阶段 A 把配置的标记作为
# 额外固定修饰搜库（理论离子带标记），predict 键去标记、余弦按子离子顺序
# 0 补齐；含无标记通道（默认）行为不变（label_tag=Unlabel、label_mods=NULL）。
ul_ch <- if (!is.null(base_cfg$unlabeled_channel) && length(base_cfg$unlabeled_channel) > 0)
  tail(base_cfg$unlabeled_channel, 1) else "1"
stageA_tag <- "unlabeled"
stageA_mods <- NULL
if (!identical(ul_ch, "1")) {
  lsp <- parse_label_spec(base_cfg$label_type)
  stageA_tag <- if (!is.null(lsp$class1)) lsp$class1 else "unlabeled"
  stageA_mods <- lsp$mods
  cat("[无标记通道] unlabeled_channel=0：阶段 A 按标记作固定修饰搜库（标签=",
      stageA_tag, "，修饰标记 ", length(stageA_mods), " 个）
", sep = "")
}
res <- stageA_evaluate(merged_file, unlabeled_files, predict_file,
                       wA, thrA, out_dir, max_cores, worker_cores = worker_cores,
                       label_tag = stageA_tag, label_mods = stageA_mods)
# 打印本步骤完成信息与输出目录
# Print the completion message and output directory for this step
cat("==== [用户第三步] 完成，输出目录：", out_dir, " ====\n")
cat("==== [User Step 3] done, output: ", out_dir, " ====\n")
cat("DONE\n")
